const directions=[{name:'A little Nashville magic',place:'Nashville, Tennessee',tag:'Late nights. Slow mornings.',image:'nashville',stay:'Your own East Nashville hideaway',house:'pool',desc:'Get ready together, follow the live music, then recover poolside. A weekend with a little main-character energy.',price:685,beds:'4 bedrooms · 5 beds · 3 baths',activity:'Make cocktails with a local',actimage:'drinks',actdesc:'A little shaking, a little sipping · $65 / person',second:'A long, leisurely Southern brunch',secondimg:'food',total:5480},{name:'Cabin, but make it a party',place:'Hudson Valley, New York',tag:'Fresh air. Very good company.',image:'cabin',stay:'A woodland escape for the whole crew',house:'interior',desc:'A cabin big enough for everyone. Hot-tub catch-ups, dinner under the stars, and absolutely no alarms.',price:540,beds:'4 bedrooms · 6 beds · 2.5 baths',activity:'A private chef, a very long dinner',actimage:'food',actdesc:'Seasonal plates, right at home · $95 / person',second:'Wine tasting, without the rush',secondimg:'drinks',total:4320},{name:'Salt air & sunset toasts',place:'Charleston, South Carolina',tag:'Beach days. Dinner dates.',image:'charleston',stay:'A sun-filled house near the shore',house:'pool',desc:'Barefoot mornings, colorful streets, and a sunset worth gathering everyone for. Just the right mix of out and in.',price:620,beds:'4 bedrooms · 5 beds · 3 baths',activity:'Sail into golden hour',actimage:'charleston',actdesc:'A private sunset sail · $85 / person',second:'Dinner with a local chef',secondimg:'food',total:4960}];
const prototypePrompt='A bachelorette for 8 this summer. About $700 each.';
let prototypeTypingTimer,prototypeTypingActive=false;
function promptDetails(text=state.prompt){const details=[];const occasion=/\bbachelorette\b/i.exec(text);if(occasion)details.push({key:'occasion',start:occasion.index,end:occasion.index+occasion[0].length,text:occasion[0],value:occasion[0]});const guest=/\bfor\s+(\d{1,2}|two)\b/i.exec(text)||/\b(\d{1,2})\s+(?:people|guests|friends)\b/i.exec(text);if(guest){const start=guest.index+guest[0].indexOf(guest[1]);details.push({key:'guests',start,end:start+guest[1].length,text:guest[1],value:guest[1].toLowerCase()==='two'?2:Number(guest[1])})}const when=/\bthis\s+(?:summer|spring|fall|winter)\b(?:, preferably in (?:January|February|March|April|May|June|July|August|September|October|November|December)(?: or (?:January|February|March|April|May|June|July|August|September|October|November|December))*)?(?: for \d+ nights?)?|\banytime\b(?: for \d+ nights?)?/i.exec(text);if(when)details.push({key:'when',start:when.index,end:when.index+when[0].length,text:when[0],value:when[0]});const budget=/\$([\d,]+)(?:\s*(?:each|per person))?/i.exec(text);if(budget)details.push({key:'budget',start:budget.index,end:budget.index+budget[0].length,text:budget[0],value:Number(budget[1].replace(/,/g,''))});const mood=/a mix of going out and switching off|late nights and city lights|long dinners and slow mornings|fresh air and cozy nights|a little adventure in the outdoors/i.exec(text);if(mood&&!occasion)details.push({key:'mood',start:mood.index,end:mood.index+mood[0].length,text:mood[0],value:mood[0]});const woods=/somewhere in the woods(?:, near (?:the Catskills|the Adirondacks|the Berkshires|the Green Mountains)(?: or (?:the Catskills|the Adirondacks|the Berkshires|the Green Mountains))*)?/i.exec(text);if(woods)details.push({key:'woods',start:woods.index,end:woods.index+woods[0].length,text:woods[0],value:woods[0]});const warmth=/somewhere warm(?:, around \d+°F)?/i.exec(text);if(warmth)details.push({key:'warmth',start:warmth.index,end:warmth.index+warmth[0].length,text:warmth[0],value:warmth[0]});return details.sort((a,b)=>a.start-b.start)}
function syncPromptDetails(){const details=promptDetails(),guests=details.find(x=>x.key==='guests'),when=details.find(x=>x.key==='when');state.guests=guests?guests.value:undefined;state.when=when?when.text.charAt(0).toUpperCase()+when.text.slice(1):undefined;const who=$('#guest-label'),date=$('#dates-label');if(who)who.textContent=guests?guests.value+' guests':'Add guests';if(date){const timing=when?timingPreferences(when):null;date.textContent=timing?[(timing.months.length?timing.months.join(' or '):timing.base.charAt(0).toUpperCase()+timing.base.slice(1)),...(timing.nights?[timing.nights+' nights']:[])].join(' · '):'I’m flexible'}}
function replacePromptDetail(key,value,live=false){const detail=promptDetails().find(x=>x.key===key);if(!detail)return;const text=key==='budget'?'$'+Number(value).toLocaleString('en-US')+' each':key==='mood'?String(value).charAt(0).toUpperCase()+String(value).slice(1):String(value);state.prompt=state.prompt.slice(0,detail.start)+text+state.prompt.slice(detail.end);syncPromptDetails();localStorage.setItem('trip-prompt',state.prompt);if(live)updatePromptEditor();else render()}
function timingPreferences(detail=promptDetails().find(x=>x.key==='when')){const text=detail?.text||'this summer',base=(/^this (summer|spring|fall|winter)|^anytime/i.exec(text)||['this summer'])[0].toLowerCase(),season=base.split(' ')[1],available=({summer:['June','July','August'],spring:['March','April','May'],fall:['September','October','November'],winter:['December','January','February']})[season]||['June','July','August'];return {base,available,months:available.filter(m=>new RegExp('\\b'+m+'\\b','i').test(text)),nights:Number(/for (\d+) nights?/i.exec(text)?.[1]||0)}}
function refineTiming(month,nights){const timing=timingPreferences();if(month==='all')timing.months=[];else if(month)timing.months=timing.available.filter(m=>m===month?!timing.months.includes(m):timing.months.includes(m));if(nights!==undefined)timing.nights=nights;replacePromptDetail('when',timing.base+(timing.months.length?', preferably in '+timing.months.join(' or '):'')+(timing.nights?' for '+timing.nights+' nights':''))}
const moodNames=['fresh air and cozy nights','a little adventure in the outdoors','long dinners and slow mornings','late nights and city lights'];
function moodFromPoint(x,y){return Math.abs(x-50)<19&&Math.abs(y-50)<19?'A mix of going out and switching off':moodNames[(y>=50?2:0)+(x>=50?1:0)]}
function wordControl(key=state.wordControl,detail=promptDetails().find(x=>x.key===key)){if(!detail)return '';const title={guests:'Who’s in the group chat?',budget:'What feels comfortable?',when:'Make a little time for it',mood:'Find your kind of weekend',occasion:'What’s her kind of weekend?',woods:'A little closer to the trees',warmth:'Your kind of warm'}[key];let control='';if(key==='guests')control=`<div class="crew-faces" aria-hidden="true">${Array.from({length:Math.min(detail.value,12)},(_,i)=>`<span style="--i:${i}">${['☺','☻','☺','☺'][i%4]}</span>`).join('')}</div><div class="word-stepper"><button data-word-step="-1" aria-label="Fewer guests" ${detail.value<=1?'disabled':''}>−</button><strong>${detail.value}<small>friends, one weekend</small></strong><button data-word-step="1" aria-label="More guests" ${detail.value>=16?'disabled':''}>+</button></div>`;if(key==='budget')control=`<div class="budget-amount"><span data-budget-amount>$${detail.value.toLocaleString('en-US')}</span><small>per person</small></div><input class="budget-range" type="range" min="200" max="2000" step="50" value="${detail.value}" aria-label="Budget per person" data-budget-range><div class="range-captions"><span>A little getaway</span><span>A little extra</span></div><div class="budget-scope">For the whole weekend</div>`;if(key==='when'){const timing=timingPreferences(detail);control=`<div class="timing-label">Preferred months <span>Pick any</span></div><div class="month-cards">${timing.available.map((month,i)=>`<button data-refine-month="${month}" aria-pressed="${timing.months.includes(month)}"><span aria-hidden="true">${['☀️','⛱️','🍦'][i%3]}</span><b>${month}</b></button>`).join('')}</div><button class="anytime-option" data-refine-month="all" aria-pressed="${!timing.months.length}">Anytime ${timing.base}</button><div class="timing-label nights-label">How many nights?</div><div class="night-chips">${[2,3,4,5].map(n=>`<button data-refine-nights="${n}" aria-pressed="${timing.nights===n}">${n}</button>`).join('')}<button data-refine-nights="0" aria-pressed="${!timing.nights}">Flexible</button></div>`;}if(key==='woods')control=woodsControl(detail);if(key==='warmth')control=warmthControl(detail);if(key==='mood'||key==='occasion'){const chosen=key==='occasion'?selectedVibe():detail.text,x=chosen?(state.moodX??50):50,y=chosen?(state.moodY??50):50;control=`<div class="mood-top">🌲 &nbsp; Out in nature</div><div class="mood-row"><span>Slow<br>mornings</span><div class="mood-pad" role="slider" tabindex="0" aria-label="Weekend energy" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${x}" aria-valuetext="${escape(chosen||'No vibe selected')}" data-mood-pad><i class="mood-axis-x"></i><i class="mood-axis-y"></i><span class="mood-sticker mood-sticker-a">🌲</span><span class="mood-sticker mood-sticker-b">🥾</span><span class="mood-sticker mood-sticker-c">☕</span><span class="mood-sticker mood-sticker-d">🪩</span><span class="mood-pin" ${chosen?'':'hidden'} style="left:${x}%;top:${y}%"></span></div><span>Late<br>nights</span></div><div class="mood-bottom">City lights &nbsp; 🌃</div><p class="mood-caption" data-mood-caption>${escape(chosen||'Still finding her vibe')}</p>`}return `<div class="prompt-popover playful-control control-${key}" popover="manual" role="dialog" aria-label="${title}"><div class="prompt-popover-head"><b>${title}</b><button data-word-close aria-label="Close adjustment">${icon('close')}</button></div>${control}<button class="word-done" data-word-close>Done</button></div>`}
const inspirationIdeas={woods:{image:'cabin',alt:'A cabin tucked into the trees',prompt:'A long weekend for two, somewhere in the woods. A fireplace, a good book, and nowhere to be.',phrase:'somewhere in the woods',ending:'A fireplace, a good book, and nowhere to be.'},warmth:{image:'pool',alt:'A sunny place with a pool',prompt:'A few days for two, somewhere warm. A pool, and really good food.',phrase:'somewhere warm',ending:'Just us, a pool, and really good food.'}};
function inspirationDraft(key){return state.inspirationDrafts?.[key]||inspirationIdeas[key].prompt}
function inspirationCards(){return `<aside class="planner-inspiration explore-inspiration"><span class="idea-eyebrow">A little inspiration</span><button class="suggestion" data-use-inspo="woods"><img src="assets/cabin.jpg" alt="A cabin in the woods"><span>A long weekend<br> somewhere in the woods<small>A fireplace, a good book, and nowhere to be.</small></span></button><button class="suggestion" data-use-inspo="warmth"><img src="assets/pool.jpg" alt="A sunny place with a pool"><span>A few days<br> somewhere warm<small>Just us, a pool, and really good food.</small></span></button></aside>`}
const woodsyAreas=[{name:'the Adirondacks',label:'Adirondacks',x:32,y:20},{name:'the Green Mountains',label:'Green Mountains',x:70,y:33},{name:'the Catskills',label:'Catskills',x:28,y:75},{name:'the Berkshires',label:'Berkshires',x:68,y:66}];
function woodsControl(detail){return `<div class="woodland-map" aria-label="Woodsy areas in the Northeast"><svg viewBox="0 0 300 215" aria-hidden="true"><path d="M-20 35Q65 5 99 39T190 29T324 48V240H-20Z" fill="#e8efdf"/><path d="M-5 156Q47 100 98 135T184 121T320 169" fill="none" stroke="#d3e1c4" stroke-width="40"/><path d="M105 -10Q147 44 130 80T149 145T128 230" fill="none" stroke="#bcd7e4" stroke-width="5"/><path d="M10 200Q74 163 109 104T202 55T304 5" fill="none" stroke="#fff" stroke-width="3" stroke-dasharray="5 5"/><g fill="#adc49b"><path d="m30 45 9-18 9 18h-7v9h-4v-9Zm145 105 10-20 10 20h-8v10h-4v-10Zm72-122 10-20 10 20h-8v10h-4v-10ZM75 195l9-18 9 18h-7v9h-4v-9Z"/></g></svg><span class="map-region-label">NORTHEAST ESCAPES</span>${woodsyAreas.map(area=>`<button style="left:${area.x}%;top:${area.y}%" data-woodland-area="${area.name}" aria-pressed="${detail.text.includes(area.name)}">${detail.text.includes(area.name)?'✓':'🌲'} ${area.label}</button>`).join('')}</div><div class="woodland-note">A few woodsy directions · Pick any</div>`}
function warmthControl(detail){const temp=Number(/around (\d+)°F/.exec(detail.text)?.[1]||78);return `<div class="warmth-weather" aria-hidden="true">☀️</div><div class="warmth-degrees"><span data-warmth-amount>${temp}°</span><small>Fahrenheit</small></div><input class="warmth-range" data-warmth-range type="range" min="65" max="95" value="${temp}" aria-label="Preferred daytime temperature"><div class="range-captions"><span>Light sweater</span><span>Pool weather</span></div>`}
function refineInspirationDetail(key,value,live=false){if(state.inspoControl){const draft=inspirationDraft(state.inspoControl),detail=promptDetails(draft).find(d=>d.key===key);if(!detail)return;state.inspirationDrafts={...state.inspirationDrafts,[state.inspoControl]:draft.slice(0,detail.start)+value+draft.slice(detail.end)};if(live){const token=document.querySelector('[data-inspo-key="'+state.inspoControl+'"]');if(token)token.textContent=value}else render()}else replacePromptDetail(key,value,live)}
function toggleWoodlandArea(area){const draft=state.inspoControl?inspirationDraft(state.inspoControl):state.prompt,detail=promptDetails(draft).find(d=>d.key==='woods');if(!detail)return;const selected=woodsyAreas.filter(a=>a.name===area?!detail.text.includes(a.name):detail.text.includes(a.name));refineInspirationDetail('woods','somewhere in the woods'+(selected.length?', near '+selected.map(a=>a.name).join(' or '):''))}
function selectedVibe(text=state.prompt){return /a mix of going out and switching off|late nights and city lights|long dinners and slow mornings|fresh air and cozy nights|a little adventure in the outdoors/i.exec(text)?.[0]}
function refineOccasionVibe(value){const existing=selectedVibe(),lower=value.toLowerCase();if(existing){const start=state.prompt.indexOf(existing);state.prompt=state.prompt.slice(0,start)+lower+state.prompt.slice(start+existing.length)}else state.prompt=state.prompt.replace(/\bbachelorette\b/i,occasion=>occasion+', with '+lower+',');syncPromptDetails();localStorage.setItem('trip-prompt',state.prompt);updatePromptEditor()}
function setMoodPoint(pad,x,y){state.moodX=Math.max(5,Math.min(95,Math.round(x)));state.moodY=Math.max(5,Math.min(95,Math.round(y)));const value=moodFromPoint(state.moodX,state.moodY);if(state.wordControl==='occasion')refineOccasionVibe(value);else replacePromptDetail('mood',value,true);const pin=pad.querySelector('.mood-pin');pin.hidden=false;pin.style.left=state.moodX+'%';pin.style.top=state.moodY+'%';pad.setAttribute('aria-valuenow',state.moodX);pad.setAttribute('aria-valuetext',value);$('[data-mood-caption]').textContent=value}
document.addEventListener('pointerdown',e=>{const pad=e.target.closest('[data-mood-pad]');if(!pad)return;e.preventDefault();pad.focus();pad.setPointerCapture(e.pointerId);const move=event=>{const rect=pad.getBoundingClientRect();setMoodPoint(pad,(event.clientX-rect.left)/rect.width*100,(event.clientY-rect.top)/rect.height*100)};move(e);pad.onpointermove=move;pad.onpointerup=pad.onpointercancel=()=>{pad.onpointermove=null;pad.onpointerup=null;pad.onpointercancel=null}});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-mood-pad]')||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();setMoodPoint(e.target,(state.moodX??50)+(e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0),(state.moodY??50)+(e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0))});
function promptMarkup(){let cursor=0,html='';for(const detail of promptDetails()){html+=escape(state.prompt.slice(cursor,detail.start))+`<span class="prompt-word" role="button" tabindex="0" contenteditable="false" data-word-control="${detail.key}" aria-label="Adjust ${detail.key==='when'?'timing':detail.key}: ${escape(detail.text)}" aria-expanded="${state.wordControl===detail.key}">${escape(detail.text)}</span>`;cursor=detail.end}return html+escape(state.prompt.slice(cursor))}
function promptEditor(){return `<div class="prompt-composer"><div id="prompt" class="interactive-idea" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Describe your trip" data-placeholder="Tell us what you’re imagining…">${promptMarkup()}</div>${wordControl()}</div>`}
function promptCaret(input){const selection=window.getSelection();if(!selection.rangeCount||!input.contains(selection.anchorNode))return state.prompt.length;const range=selection.getRangeAt(0).cloneRange();range.selectNodeContents(input);range.setEnd(selection.anchorNode,selection.anchorOffset);return range.toString().length}
function updatePromptEditor(caret){const input=$('#prompt');if(!input)return;input.innerHTML=promptMarkup();positionWordControl();if(caret===undefined)return;const selection=window.getSelection(),range=document.createRange(),walker=document.createTreeWalker(input,NodeFilter.SHOW_TEXT);let node,remaining=caret;while(node=walker.nextNode()){if(remaining<=node.length){if(node.parentElement.closest('[contenteditable="false"]'))range.setStartAfter(node.parentElement);else range.setStart(node,remaining);range.collapse(true);selection.removeAllRanges();selection.addRange(range);return}remaining-=node.length}range.selectNodeContents(input);range.collapse(false);selection.removeAllRanges();selection.addRange(range)}
function positionWordControl(){const popover=$('.prompt-popover'),token=document.querySelector('.prompt-word[aria-expanded="true"]');if(!popover||!token)return;if(popover.showPopover&&!popover.matches(':popover-open'))popover.showPopover();const fragments=token.getClientRects(),rect=fragments[fragments.length-1]||token.getBoundingClientRect(),top=rect.bottom+10;popover.style.maxHeight=Math.max(60,window.innerHeight-top-16)+'px';popover.style.overflowY='auto';popover.style.top=top+'px';popover.style.left=Math.max(16,Math.min(rect.left,window.innerWidth-popover.offsetWidth-16))+'px'}
document.addEventListener('scroll',positionWordControl,true);window.addEventListener('resize',positionWordControl);
function stopPrototypeTyping(){clearTimeout(prototypeTypingTimer);prototypeTypingActive=false}
function finishPrototypeTyping(){if(!prototypeTypingActive)return;stopPrototypeTyping();state.prompt=prototypePrompt;state.promptReviewed=true;syncPromptDetails();localStorage.setItem('trip-prompt',state.prompt);updatePromptEditor(document.activeElement===$('#prompt')?state.prompt.length:undefined)}
function typePrototypePrompt(input){if(input.textContent.trim()||prototypeTypingActive)return;prototypeTypingActive=true;let cursor=0;const tick=()=>{const target=$('#prompt');if(!target){stopPrototypeTyping();return}cursor++;state.prompt=prototypePrompt.slice(0,cursor);state.promptReviewed=true;syncPromptDetails();updatePromptEditor(document.activeElement===target?cursor:undefined);if(cursor<prototypePrompt.length){prototypeTypingTimer=setTimeout(tick,/[,\.]/.test(prototypePrompt[cursor-1])?100:23)}else{stopPrototypeTyping();localStorage.setItem('trip-prompt',state.prompt)}};if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){finishPrototypeTyping();return}prototypeTypingTimer=setTimeout(tick,220)}
document.addEventListener('focusin',e=>{if(e.target.id==='prompt')typePrototypePrompt(e.target)});
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-word-control]'))stopPrototypeTyping();if(e.target.id==='prompt'&&!prototypeTypingActive&&!e.target.textContent.trim())typePrototypePrompt(e.target)});
document.addEventListener('paste',e=>{if(e.target.id!=='prompt')return;e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))});
let state={screen:location.hash==='#search'?'search':'home',prompt:'',selected:1,tab:'The weekend',updated:'',saved:localStorage.getItem('trip-saved')==='true',party:false};const escape=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}function go(screen){if(state.generation)cancelGeneration();if(screen==='ideas'||screen==='trip'){localStorage.setItem('trip-prompt',state.prompt);location.href='weekend/#home';return}state.screen=screen;history.replaceState(null,'',screen==='search'?'#search':location.pathname);render();window.scrollTo(0,0)}function nav(){return `<nav class="bottom-nav">${[['search','Explore','home'],['heart','Wishlists','saved'],['trip','Trips','saved'],['message','Messages','messages'],['profile','Profile','profile']].map(([i,l,a])=>`<button class="${state.screen==='home'&&a==='home'?'selected':''}" data-action="${a}">${icon(i)}${l}</button>`).join('')}</nav>`}function listing(name,photo,price,rating){return `<button class="listing" data-action="listing"><div class="photo"><img src="${img(photo)}" alt="${name}"><span class="badge">Guest favorite</span><span class="heart">♡</span></div><strong>${name}</strong><span class="small muted">$${price} for 2 nights · ★ ${rating}</span></button>`}
function webHeader(){return `<header class="web-header"><button class="web-brand" data-action="home" aria-label="Airbnb home"><svg class="airbnb-belo" width="30" height="32" aria-hidden="true" viewBox="69 64 142 152" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M202.958 157.86C192.603 135.329 181.256 112.469 169.689 89.9378C167.596 85.7614 163.63 77.7383 160.105 73.4519C155.037 67.2972 147.546 64 139.945 64C132.344 64 124.853 67.2972 119.785 73.4519C116.26 77.7383 112.294 85.7614 110.201 89.9378C98.6338 112.469 87.287 135.329 76.9317 157.86C75.6098 160.827 72.4151 167.861 71.2033 171.048C69.7711 174.895 69 179.072 69 183.248C69 201.383 83.211 216 102.159 216C117.802 216 130.251 205.999 139.945 195.557C149.639 205.999 162.088 216 177.731 216C196.679 216 211 201.383 211 183.248C211 179.072 210.119 174.895 208.687 171.048C207.475 167.861 204.28 160.827 202.958 157.86ZM139.945 178.082C132.123 167.971 124.853 155.442 124.853 145.33C124.853 135.219 132.013 130.163 139.945 130.163C147.877 130.163 155.147 135.549 155.147 145.33C155.147 155.112 147.766 167.971 139.945 178.082ZM177.731 204.68C166.146 204.68 156.209 196.597 147.408 186.886C156.483 175.594 166.494 159.608 166.494 145.33C166.494 128.515 153.385 118.843 139.945 118.843C126.505 118.843 113.506 128.515 113.506 145.33C113.506 159.605 123.447 175.585 132.489 186.877C123.687 196.593 113.747 204.68 102.159 204.68C89.6005 204.68 80.3468 195.118 80.3468 183.248C80.3468 180.39 80.7874 177.753 81.7789 175.005C82.7704 172.477 85.9651 165.443 87.287 162.696C97.6424 140.165 108.769 117.524 120.336 94.9935C122.429 90.8171 125.954 83.893 128.598 80.7057C131.462 77.1887 135.428 75.3203 139.945 75.3203C144.462 75.3203 148.427 77.1887 151.292 80.7057C153.936 83.893 157.461 90.8171 159.554 94.9935C171.121 117.524 182.247 140.165 192.603 162.696C193.925 165.443 197.119 172.477 198.111 175.005C199.102 177.753 199.653 180.39 199.653 183.248C199.653 195.118 190.289 204.68 177.731 204.68Z" fill="currentColor"/>
</svg><span>airbnb</span></button><nav class="web-categories" aria-label="Explore Airbnb"><button class="selected" data-action="category"><span>🏡</span>Homes</button><button data-action="category"><span>🎈</span>Experiences</button><button data-action="category"><span>🛎️</span>Services</button></nav><div class="web-account"><button data-action="profile">Become a host</button><button class="round" data-action="profile" aria-label="Language and currency">◎</button><button class="round" data-action="profile" aria-label="Account menu">☰</button></div></header>`}
function webSearchBar(){return `<button class="unified-search" data-action="search"><span class="unified-search-icon">${icon('search')}</span><span><b>Where to?</b><small>A destination, a trip idea, a reason to get away…</small></span><span class="unified-search-cta">Start exploring ${icon('search')}</span></button>`}
function webStay(name,image,price,rating,destination){return `<article class="web-stay"><button data-destination="${destination}" class="web-stay-link"><div class="web-stay-photo"><img src="${img(image)}" alt="${name}"><span class="badge">Guest favorite</span><span class="heart">♡</span></div><strong>${name}</strong><span class="small muted">$${price} for 3 nights · ★ ${rating}</span></button></article>`}
function home(){return `${webHeader()}<section class="web-search-area">${webSearchBar()}</section><div class="web-home"><section class="web-imagine"><div><span class="idea-eyebrow">A new way to get away</span><h1>Every great trip starts<br>with a little “what if.”</h1><p>A bachelorette. A change of scenery. Somewhere you haven’t thought of yet.</p><button class="black" data-action="search" data-entry-start="explore">Imagine a trip</button></div><div class="idea-collage" aria-hidden="true"><img class="collage-one" src="assets/cabin.jpg" alt=""><img class="collage-two" src="assets/charleston.jpg" alt=""><span>Where could this go?</span></div></section><section class="web-shelf"><div class="section-title"><h2>Homes for your next long weekend</h2><div class="shelf-controls"><button class="round" data-action="search" aria-label="Explore more homes">›</button></div></div><div class="web-listings">${webStay('A chalet in the Hudson Valley','listing-hudson-0',1620,'4.98','hudson')}${webStay('A poolside home in East Nashville','listing-nashville-0',2055,'4.98','nashville')}${webStay('A historic Charleston escape','listing-charleston-0',1860,'4.88','charleston')}${webStay('A cabin in the woods','listing-hudson-alt-0',1755,'4.92','hudson')}${webStay('A plunge pool in Five Points','listing-nashville-alt-0',1965,'4.9','nashville')}${webStay('Room for everyone in Charleston','listing-charleston-alt-0',1680,'4.86','charleston')}</div></section><section class="web-bottom"><div><h2>A few possibilities. One very good weekend.</h2><p>Give your next group chat something to get excited about.</p></div><button class="pill" data-action="saved">Open your Weekend Edit</button></section></div><footer class="web-footer"><span>© 2026 Airbnb</span><span>English (US) &nbsp; · &nbsp; $ USD</span></footer>`}
function exploreSearch(){return `<div class="search-backdrop" inert aria-hidden="true">${home()}</div><div class="web-search-overlay"><section class="web-planner consistent-planner" role="dialog" aria-modal="true" aria-label="Imagine a trip"><div class="planner-top"><span>Start planning your next trip</span><button class="close" data-action="home" aria-label="Close search">${icon('close')}</button></div>${entryModes()}<div class="planner-grid"><div class="planner-main"><span class="idea-eyebrow">Start anywhere</span><h1>What’s the trip<br>on your mind?</h1><p>You don’t need a destination. Just a little idea.</p>${promptEditor()}<div class="planner-details"><button data-action="dates">${icon('calendar')}<span>When<b id="dates-label">${escape(state.when||'I’m flexible')}</b></span></button><button data-action="guests">${icon('profile')}<span>Who<b id="guest-label">${state.guests?state.guests+' guests':'Add guests'}</b></span></button></div></div>${inspirationCards()}</div><div class="planner-footer"><button class="text-link" data-action="clear">Clear all</button><button class="pink" data-action="generate">${icon('spark')} Imagine my trip</button></div></section></div>`}
function entryModes(){const direct=state.entryMode==='direct';return `<div class="entry-modes" role="tablist" aria-label="How would you like to plan?"><button id="explore-mode" role="tab" aria-selected="${!direct}" aria-controls="entry-panel" data-entry-mode="explore">Help me explore</button><button id="direct-mode" role="tab" aria-selected="${direct}" aria-controls="entry-panel" data-entry-mode="direct">I know what I want</button></div>`}
function search(){return state.entryMode==='direct'?directSearch():exploreSearch().replace('<div class="planner-grid">','<div class="planner-grid" id="entry-panel" role="tabpanel" aria-labelledby="explore-mode">')}
function nativeDateLabel(){return state.exactStart?new Date(state.exactStart+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})+(state.exactEnd?' – '+new Date(state.exactEnd+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}):''): 'Add dates'}
function nativeGuestLabel(){const n=(state.exactGuests||0)+(state.children||0);return n?n+' '+(n===1?'guest':'guests')+(state.infants?', '+state.infants+' infants':''):'Add guests'}
function directSearch(){const field=state.nativeField||'where';return `<div class="search-backdrop" inert aria-hidden="true">${home()}</div><div class="web-search-overlay"><section class="web-planner mobile-direct consistent-planner" role="dialog" aria-modal="true" aria-label="Search Airbnb"><div class="planner-top"><span>Start planning your next trip</span><button class="close" data-action="home" aria-label="Close search">${icon('close')}</button></div>${entryModes()}<form id="direct-search"><div id="entry-panel" role="tabpanel" aria-labelledby="direct-mode" class="planner-grid direct-planner-grid"><div class="mobile-search-body">${field==='where'?`<section class="mobile-search-card"><h2>Where?</h2><div class="mobile-destination-input">${icon('search')}<input id="destination" name="destination" placeholder="Search destinations" aria-label="Search destinations" value="${escape(state.destination||'')}" autocomplete="off"></div><p class="destination-hint">Search a city, neighborhood, or address.</p></section>`:`<button type="button" class="collapsed" data-native-field="where"><span>Where</span><b>${escape(state.destination||'Search destinations')}</b></button><input type="hidden" id="destination" name="destination" value="${escape(state.destination||'')}">`}${field==='dates'?`<section class="mobile-search-card mobile-date-card"><h2>When’s your trip?</h2>${nativeCalendar()}</section>`:`<button type="button" class="collapsed" data-native-field="dates"><span>When</span><b>${nativeDateLabel()}</b></button>`}${field==='guests'?`<section class="mobile-search-card"><h2>Who’s coming?</h2>${nativeGuests()}</section>`:`<button type="button" class="collapsed" data-native-field="guests"><span>Who</span><b>${nativeGuestLabel()}</b></button>`}<input type="hidden" name="check_in" value="${state.exactStart||''}"><input type="hidden" name="check_out" value="${state.exactEnd||''}"><input type="hidden" name="adults" value="${state.exactGuests||1}"><p id="direct-error" class="direct-error" role="alert"></p></div>${directInspiration()}</div><div class="planner-footer"><button class="text-link" type="button" data-clear-native>Clear all</button><button class="pink" type="submit">${icon('search')} Search</button></div></form></section></div>`}
function directInspiration(){return `<aside class="planner-inspiration direct-inspiration"><span class="idea-eyebrow">A little inspiration</span>${[['Nashville, Tennessee','nashville','Live music & late nights'],['Charleston, South Carolina','charleston','Salt air & pastel streets'],['Hudson Valley, New York','cabin','A little room to slow down']].map(([place,image,desc])=>`<button type="button" class="suggestion" data-native-place="${place}"><img src="${img(image)}" alt="${place}"><span>${place}<small>${desc}</small></span></button>`).join('')}<p>A few places to start. Pick one, then make the dates yours.</p></aside>`}
function nativeDestinations(){return `<div class="native-suggest-title">Suggested destinations</div>${[['Nashville, Tennessee','For live music and late nights','🎸'],['Charleston, South Carolina','For pastel streets and ocean air','🏛️'],['Hudson Valley, New York','For a weekend in the woods','🌲']].map(([place,desc,symbol])=>`<button type="button" class="native-destination" data-native-place="${place}"><span class="native-destination-icon">${symbol}</span><span><b>${place}</b><small>${desc}</small></span></button>`).join('')}`}
function nativeCalendar(){const base=state.calendarBase??(state.exactStart?new Date(state.exactStart+'T12:00:00').getFullYear()*12+new Date(state.exactStart+'T12:00:00').getMonth():2026*12+10);return `<div class="native-calendar-nav"><button type="button" data-month-step="-1" aria-label="Previous month">‹</button><span>Choose your dates</span><button type="button" data-month-step="1" aria-label="Next month">›</button></div><div class="native-months">${[0,1].map(offset=>{const month=new Date(Math.floor((base+offset)/12),(base+offset)%12,1),year=month.getFullYear(),m=month.getMonth(),days=new Date(year,m+1,0).getDate();return `<div class="native-month"><h3>${month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h3><div class="native-weekdays">${['S','M','T','W','T','F','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="native-days">${'<span></span>'.repeat(month.getDay())}${Array.from({length:days},(_,i)=>{const date=year+'-'+String(m+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0'),selected=date===state.exactStart||date===state.exactEnd,inRange=state.exactStart&&state.exactEnd&&date>state.exactStart&&date<state.exactEnd;return `<button type="button" data-native-day="${date}" class="${selected?'selected ':''}${inRange?'in-range':''}" ${date<'2026-11-19'?'disabled':''} aria-label="${month.toLocaleDateString('en-US',{month:'long'})} ${i+1}, ${year}${date===state.exactStart?', check in':date===state.exactEnd?', check out':''}" aria-pressed="${selected}">${i+1}</button>`}).join('')}</div></div>`}).join('')}</div><div class="native-popover-footer"><button class="text-link" type="button" data-clear-dates>Clear dates</button><button type="button" class="black" data-native-field="guests">Done</button></div>`}
function nativeGuests(){return `<div class="native-guest-list">${[['exactGuests','Adults','Ages 13 or above'],['children','Children','Ages 2–12'],['infants','Infants','Under 2'],['pets','Pets','Bringing an assistance animal?']].map(([key,label,desc])=>`<div class="native-guest-row"><span><b>${label}</b><small>${desc}</small></span><div><button type="button" data-guest-key="${key}" data-guest-step="-1" aria-label="Remove ${label.toLowerCase()}" ${!state[key]?'disabled':''}>−</button><span>${state[key]||0}</span><button type="button" data-guest-key="${key}" data-guest-step="1" aria-label="Add ${label.toLowerCase()}">+</button></div></div>`).join('')}</div><p class="native-guest-note">Search opens Airbnb in a new tab.</p>`}
function ideas(){return `<div class="fade"><header class="bar">${round('back','search','Back to your idea')}<div class="bar-title">A trip taking shape<small>Your idea, a few possibilities</small></div>${round('close','home','Close')}</header><div class="intro"><h2>Same crew.<br>Three ways to get away.</h2><p>Somewhere between a big night out and a really good night in. What feels like your people?</p><div class="brief"><span>🥂 Bachelorette</span><span>8 guests</span><span>3 nights · Flexible</span></div><button class="text-link" style="margin-top:15px;font-size:12px" data-action="search">Edit your idea</button></div>${directions.map((d,i)=>`<article class="direction"><div class="direction-photo" role="button" tabindex="0" data-select="${i}" aria-label="Explore ${d.place}"><img src="${img(d.image)}" alt="${d.place}"><div class="direction-caption"><span>${d.tag}</span><h2>${d.name}</h2></div></div><div class="direction-body"><p>${d.desc}</p><div class="cost"><span><b>$${d.price}</b> / person est.<br><span class="muted">Stay + a few good plans</span></span><button class="black" data-select="${i}">Explore this weekend</button></div></div></article>`).join('')}<p class="footnote">A starting point, with room to make it yours.<br>Illustrative prices. Nothing is booked.</p></div>`}
function trip(){const d=directions[state.selected];return `<div class="fade"><div class="hero"><img src="${img(d.image)}" alt="${d.place}"><div class="hero-tools">${round('back','ideas','Back to possibilities')}<div>${round('heart','save',state.saved?'Saved':'Save trip')}${round('share','share','Share trip')}</div></div><div class="hero-text"><small>Our kind of getaway</small><h1>${d.name}</h1><p>${d.place} · 3 nights · 8 guests</p></div></div><div class="trip-tabs">${['The weekend','The details','Saved'].map(t=>`<button class="${state.tab===t?'selected':''}" data-tab="${t}">${t}</button>`).join('')}</div><div class="trip-content">${state.tab==='The weekend'?weekend(d):state.tab==='The details'?details(d):savedContent()}</div></div><div class="edit-dock"><button class="edit-button" data-action="edit"><span class="spark">✧</span><span>Make it more you</span><span style="margin-left:auto">${icon('message')}</span></button></div>`}
function weekend(d){return `${state.updated?`<div class="updated">✧ ${escape(state.updated)}</div>`:''}<div class="people"><span class="avatar">You</span><span class="avatar" style="background:#eee">+</span><small>Your idea. Even better with everyone.</small><button class="text-link" data-action="share" style="margin-left:auto;font-size:12px">Invite</button></div><h2>A little ${state.selected===1?'wild.<br>A little winding down.':'out.<br>A little all together.'}</h2><p>${d.desc}</p><section class="trip-section"><h3>Somewhere to make yourselves at home</h3><div class="stay-photo"><img src="${img(d.house)}" alt="${d.stay}"><span class="badge">Guest favorite</span></div><div class="stay-line"><b>${d.stay}</b><span>★ 4.98</span></div><p class="small muted">${d.beds}</p><button class="text-link" data-action="swap" style="font-size:12px">Try a different stay</button></section><section class="trip-section"><h3>A few things you could get up to</h3><p class="small muted">Room for plans. Plenty of room for no plans.</p><button class="activity" data-action="activity"><img src="${img(d.actimage)}" alt="${d.activity}"><div><strong>${d.activity}</strong><span>${d.actdesc}<br>♡ Save to the weekend</span></div></button><button class="activity" data-action="activity"><img src="${img(state.party?'drinks':d.secondimg)}" alt="Weekend activity"><div><strong>${state.party?'One night out, just for the girls':d.second}</strong><span>${state.party?'A car service, cocktails & dancing':'A little local flavor · No rush'}<br>♡ Save to the weekend</span></div></button></section><section class="trip-section"><div class="stay-line"><h3>A little budget reality check</h3><b>$${d.price}${state.party?' + 45':''}</b></div><p class="small muted">Estimated per person for your stay and these activities. Travel and meals are extra.</p><button class="text-link" data-tab="The details" style="font-size:13px">See the breakdown</button></section>`}
function details(d){return `<h2>The practical bits.</h2><p>All in one place, as the weekend comes together.</p><div class="budget-row"><b>Estimated per person</b><b>$${d.price+(state.party?45:0)}</b></div><div class="budget-row"><span>Stay · 3 nights</span><span>$${d.price-160}</span></div><div class="budget-row"><span>Experiences & activities</span><span>$${160+(state.party?45:0)}</span></div><p class="small muted" style="margin-top:12px">Estimates, including stay fees. Flights, transportation and other meals aren’t included. Nothing is booked.</p>${state.selected===2?'<p class="small muted">Photo: <a href="https://commons.wikimedia.org/wiki/File:Rainbow_Row_Charleston.jpg" target="_blank" rel="noopener">Rainbow Row, Charleston — Melizabethi123</a>, <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a>. Display cropped to fit.</p>':''}<section class="trip-section"><h3>Getting there</h3><p class="small muted">Add where you’re starting from to explore travel options together.</p><button class="pill" data-action="origin">Add departure city</button></section><section class="trip-section"><h3>Bookings & little details</h3><p class="small muted">A home for confirmations, tickets, and whatever you need on the day.</p><div id="files"></div><button class="pill" data-action="upload">＋ Add a confirmation or ticket</button><input type="file" id="upload" hidden accept=".pdf,image/*,.txt"></section>`}
function savedContent(){return `<h2>The keepers.</h2><p>Save the things you’re excited about while you explore.</p>${state.saved?`<div class="file">${icon('heart')}<div><strong>This whole weekend</strong><small>Saved to your trips</small></div></div>`:''}${(state.activities||[]).map(a=>`<div class="file">${icon('heart')}<div><strong>${escape(a)}</strong><small>Something to look forward to</small></div></div>`).join('')}${!state.saved&&!state.activities?.length?'<div class="empty-state"><span class="spark">♡</span><h3>Something catch your eye?</h3><p class="small muted">Your saved ideas will be right here.</p></div>':''}`}
function render(){if(state.promptReviewed)syncPromptDetails();document.querySelectorAll('[data-jump]').forEach(b=>b.classList.toggle('active',b.dataset.jump===state.screen));document.body.classList.toggle('planning',state.screen==='search'&&(!state.generation||state.generation.phase===0));app.innerHTML=state.generation?generationView():state.screen==='home'?home():state.screen==='search'?search():state.screen==='ideas'?ideas():trip();if(state.tab==='The details'&&state.screen==='trip')renderFiles();positionWordControl()}
function modal(html){const el=document.createElement('div');el.className='overlay';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true"><div class="handle"></div>${html}</section>`;$('.device').append(el);el.addEventListener('click',e=>{if(e.target===el||e.target.closest('[data-dismiss]'))el.remove()});return el}function heading(t){return `<div class="modal-header"><h2>${t}</h2><button data-dismiss aria-label="Close">${icon('close')}</button></div>`}
function edit(){const el=modal(`${heading('Make it more you')}<p class="small muted">Keep what you love. Change whatever you like.</p><textarea id="refine" placeholder="What would make this your kind of weekend?"></textarea><div class="chips">${['Add one big night out','Keep it under $600 each','More time doing nothing','Somewhere we can walk'].map(s=>`<button data-refine="${s}">${s}</button>`).join('')}</div><button class="pink wide" id="update">Update our weekend</button>`);el.querySelectorAll('[data-refine]').forEach(b=>b.onclick=()=>{$('#refine').value=b.dataset.refine});$('#update').onclick=()=>{const v=$('#refine').value.trim();if(!v)return $('#refine').focus();el.remove();state.party=/night|party|danc/i.test(v);if(/600|budget|cheap/i.test(v)){state.selected=1;state.updated='A little easier on the budget. Kept the cabin and made more room for nights in.'}else if(/walk/i.test(v)){state.selected=0;state.updated='Swapped in a walkable Nashville neighborhood, with good food and music nearby.'}else if(/nothing|slow|chill/i.test(v)){state.party=false;state.updated='Slowed things down. A long dinner and plenty of unplanned time.'}else state.updated=state.party?'Kept the cozy cabin. Added one big night out, with a ride there and back.':`A new direction to explore: “${v}”`;state.tab='The weekend';loading('A little more your kind of trip.',()=>go('trip'))}}
function loading(title,fn){document.body.classList.remove('planning');app.innerHTML=`<div class="loading"><div><span class="spark">✧</span><h2>${title}</h2><p>Making room for the things you love.</p><div class="dots"></div></div></div>`;setTimeout(fn,1350)}function renderFiles(){const target=$('#files');if(target)target.innerHTML=(state.files||[]).map(f=>`<div class="file">▤ <div><strong>${escape(f)}</strong><small>Added to this trip · stored for this session</small></div></div>`).join('')}
document.addEventListener('input',e=>{if(e.target.matches('[data-warmth-range]')){refineInspirationDetail('warmth','somewhere warm, around '+e.target.value+'°F',true);$('[data-warmth-amount]').textContent=e.target.value+'°';return}if(e.target.matches('[data-budget-range]')){replacePromptDetail('budget',Number(e.target.value),true);$('[data-budget-amount]').textContent='$'+Number(e.target.value).toLocaleString('en-US');return}const fieldMap={destination:'destination','exact-start':'exactStart','exact-end':'exactEnd','exact-guests':'exactGuests'};if(fieldMap[e.target.id]){state[fieldMap[e.target.id]]=e.target.id==='exact-guests'?Number(e.target.value):e.target.value;if(e.target.id==='exact-start')$('#exact-end').min=e.target.value;}if(e.target.id==='prompt'){stopPrototypeTyping();e.target.classList.remove('prototype-typing');const caret=promptCaret(e.target);state.inspoControl=null;state.prompt=e.target.textContent;state.promptReviewed=!!state.prompt.trim();state.wordControl=null;$('.prompt-popover')?.remove();syncPromptDetails();updatePromptEditor(caret);localStorage.setItem('trip-prompt',state.prompt)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.wordControl||state.inspoControl){state.inspoControl=null;state.wordControl=null;render();return}if($('.overlay'))$('.overlay').remove();else if(state.screen==='search')go('home')}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-select],[data-word-control]')&&e.target.tagName!=='BUTTON'){e.preventDefault();e.target.click()}});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-select],[data-word-control],[data-use-inspo]');if(!b)return;if(b.dataset.inspoKey){state.wordControl=null;state.inspoControl=state.inspoControl===b.dataset.inspoKey?null:b.dataset.inspoKey;render();return}if(b.dataset.useInspo){if(e.target.closest('.prompt-popover'))return;stopPrototypeTyping();state.prompt=inspirationDraft(b.dataset.useInspo);state.promptReviewed=true;state.inspoControl=null;state.wordControl=null;syncPromptDetails();localStorage.setItem('trip-prompt',state.prompt);render();return}if(b.dataset.woodlandArea){toggleWoodlandArea(b.dataset.woodlandArea);return}if(b.dataset.wordControl){stopPrototypeTyping();state.inspoControl=null;state.wordControl=state.wordControl===b.dataset.wordControl?null:b.dataset.wordControl;render();return}if(b.hasAttribute('data-word-close')){state.inspoControl=null;state.wordControl=null;render();return}if(b.dataset.refineMonth){refineTiming(b.dataset.refineMonth);return}if(b.dataset.refineNights!==undefined){refineTiming(null,Number(b.dataset.refineNights));return}if(b.dataset.wordStep){const detail=promptDetails().find(x=>x.key===state.wordControl);if(detail)replacePromptDetail(detail.key,Math.max(detail.key==='guests'?1:100,Math.min(detail.key==='guests'?16:10000,detail.value+Number(b.dataset.wordStep))));return}if(b.dataset.wordValue){replacePromptDetail(state.wordControl,b.dataset.wordValue);return}if(b.dataset.jump){go(b.dataset.jump);return}if(b.dataset.select!==undefined){state.selected=+b.dataset.select;state.updated='';state.party=false;state.tab='The weekend';go('trip');return}if(b.dataset.tab){state.tab=b.dataset.tab;render();return}if(b.dataset.prompt){stopPrototypeTyping();state.prompt=b.dataset.prompt;state.promptReviewed=true;state.editingPrompt=false;state.wordControl=null;syncPromptDetails();localStorage.setItem('trip-prompt',state.prompt);render();return}if(b.dataset.destination){location.href='weekend/#'+b.dataset.destination;return}if(b.dataset.entryMode){state.entryMode=b.dataset.entryMode;render();document.querySelector('[data-entry-mode="'+state.entryMode+'"]')?.focus();return}if(b.dataset.place){state.destination=b.dataset.place;$('#destination').value=state.destination;$('#destination').focus();return}if(b.hasAttribute('data-clear-native')){state.destination='';state.exactStart='';state.exactEnd='';state.exactGuests=0;state.children=0;state.infants=0;state.pets=0;state.nativeField='where';render();return}if(b.dataset.nativeField){state.nativeField=b.dataset.nativeField;render();return}if(b.dataset.nativePlace){state.destination=b.dataset.nativePlace==='Nearby'?'Nearby':b.dataset.nativePlace;state.nativeField='dates';render();return}if(b.dataset.monthStep){const base=state.calendarBase??(state.exactStart?new Date(state.exactStart+'T12:00:00').getFullYear()*12+new Date(state.exactStart+'T12:00:00').getMonth():2026*12+10);state.calendarBase=Math.max(2026*12+10,base+Number(b.dataset.monthStep));render();return}if(b.dataset.nativeDay){const date=b.dataset.nativeDay;if(!state.exactStart||state.exactEnd||date<=state.exactStart){state.exactStart=date;state.exactEnd=''}else state.exactEnd=date;render();return}if(b.hasAttribute('data-clear-dates')){state.exactStart='';state.exactEnd='';render();return}if(b.dataset.guestKey){const key=b.dataset.guestKey;state[key]=Math.max(0,Math.min(16,(state[key]||0)+Number(b.dataset.guestStep)));render();return}if(b.dataset.entryStart)state.entryMode=b.dataset.entryStart;const a=b.dataset.action;if(['home','search','ideas'].includes(a)){go(a);return}if(a==='clear'){stopPrototypeTyping();state.prompt='';state.promptReviewed=false;state.editingPrompt=false;state.wordControl=null;state.guests=undefined;state.when=undefined;localStorage.removeItem('trip-prompt');render();return}if(a==='generate'){finishPrototypeTyping();if(!state.prompt.trim()){state.prompt='A bachelorette for 8 this summer. A fun night out or a cozy cabin weekend.'}startGeneration();return}if(a==='edit')edit();if(a==='save'){state.saved=!state.saved;localStorage.setItem('trip-saved',state.saved);toast(state.saved?'Weekend saved to your trips':'Weekend removed from saved');}if(a==='saved'){location.href='weekend/#home';return;if(state.saved){state.tab='The weekend';go('trip')}else{modal(`${heading('Your trips start here')}<p class="muted">Imagine a weekend, then tap the heart to keep it here.</p><button class="pink wide" data-dismiss data-action="search">Imagine a trip</button>`)}}if(a==='dates'&&state.promptReviewed&&promptDetails().some(x=>x.key==='when')){state.wordControl='when';render();return}if(a==='dates'){const el=modal(`${heading('When are you thinking?')}<div class="chips">${['This spring','This summer','This fall','Anytime'].map(v=>`<button data-date="${v}">${v}</button>`).join('')}</div>`);el.querySelectorAll('[data-date]').forEach(x=>x.onclick=()=>{state.when=x.dataset.date;el.remove();render()})}if(a==='guests'&&state.promptReviewed&&promptDetails().some(x=>x.key==='guests')){state.wordControl='guests';render();return}if(a==='guests'){const el=modal(`${heading('Who’s coming?')}<p class="muted">There’s room for the whole crew.</p><div style="display:flex;align-items:center;justify-content:space-between;margin:25px 0"><b>Guests</b><div><button class="pill" id="minus">−</button> <b id="count">8</b> <button class="pill" id="plus">＋</button></div></div><button class="pink wide" id="guest-done">Done</button>`);let count=state.guests||8;$('#minus').onclick=()=>{$('#count').textContent=count=Math.max(1,count-1)};$('#plus').onclick=()=>{$('#count').textContent=++count};$('#guest-done').onclick=()=>{state.guests=count;el.remove();render()}}if(a==='share'){const d=directions[state.selected];const el=modal(`${heading('Better with your people')}<p class="muted small">Send the idea around. There’s still plenty of room to make it everyone’s weekend.</p><div class="share-preview"><img src="${img(d.image)}" alt=""><div><b>${d.name}</b><p>3 nights · 8 guests · A work in progress</p></div></div><button class="pink wide" id="copy">Copy trip link</button><p class="footnote" style="padding:15px 0 0;margin:0">Prototype link only. Live collaboration isn’t connected.</p>`);$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+location.pathname+'#trip='+state.selected);toast('Prototype trip link copied')}catch{toast('Copy this page’s URL to share the prototype')}el.remove()}}if(a==='swap'){const el=modal(`${heading('A different place to land')}<p class="small muted">Same weekend. A fresh setting.</p><div class="listing-row" style="padding:0">${listing('A bright house with a pool','pool',1850,'4.97')}${listing('A quiet woodland hideaway','cabin',1600,'4.99')}</div>`);el.querySelectorAll('[data-action="listing"]').forEach((x,i)=>x.onclick=ev=>{ev.stopPropagation();directions[state.selected].house=i?'cabin':'pool';directions[state.selected].stay=i?'A quiet woodland hideaway':'A bright house with a pool';el.remove();render();toast('A new stay for your weekend')})}if(a==='activity'){const title=b.querySelector('strong').textContent;state.activities=state.activities||[];if(!state.activities.includes(title))state.activities.push(title);toast('Saved to the weekend')}if(a==='upload')$('#upload').click();if(a==='origin'){const el=modal(`${heading('Where are you starting?')}<p class="small muted">Keep your departure city with the trip.</p><input id="city" placeholder="City or airport" aria-label="Departure city"><button class="pink wide" id="city-done">Save departure city</button>`);$('#city-done').onclick=()=>{const city=$('#city').value.trim();if(city){el.remove();toast(`Departure city saved: ${city}. Live fares aren’t connected.`)}}}if(a==='listing'&&!$('.overlay')){state.selected=1;state.tab='The weekend';go('trip')}if(a==='category'){b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');toast('Explore a trip to bring homes and experiences together')}if(a==='messages'||a==='profile')modal(`${heading(a==='messages'?'Make plans together':'Your travel space')}<p class="muted">This concept focuses on imagining and shaping a trip. Start exploring to make a weekend yours.</p><button class="pink wide" data-action="search" data-dismiss>Imagine a trip</button>`)});
document.addEventListener('change',e=>{if(e.target.id==='upload'&&e.target.files.length){state.files=state.files||[];state.files.push(e.target.files[0].name);renderFiles();toast('Added to this trip for this session')}});if(location.hash.startsWith('#trip=')){state.selected=Math.max(0,Math.min(2,Number(location.hash.split('=')[1])||0));state.screen='trip'}render();

if(['#nashville','#hudson','#charleston'].includes(location.hash))location.replace('weekend/'+location.hash);

document.addEventListener('submit',e=>{if(e.target.id!=='direct-search')return;e.preventDefault();const f=e.target,destination=f.elements.destination.value.trim(),start=f.elements.check_in.value,end=f.elements.check_out.value;if(!destination){state.nativeField='where';render();$('#destination').focus();return}if((start&&!end)||(!start&&end)||(start&&end&&end<=start)){$('#direct-error').textContent='Choose a check-in and check-out date, or leave both open.';return}const url=new URL('https://www.airbnb.com/s/'+encodeURIComponent(destination)+'/homes');url.searchParams.set('adults',f.elements.adults.value);for(const key of ['children','infants','pets'])if(state[key])url.searchParams.set(key,state[key]);if(start){url.searchParams.set('check_in',start);url.searchParams.set('check_out',end)}window.open(url.href,'_blank','noopener');});

document.addEventListener('keydown',e=>{if(e.target.matches('[data-entry-mode]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();state.entryMode=state.entryMode==='direct'?'explore':'direct';render();document.querySelector('[data-entry-mode="'+state.entryMode+'"]').focus()}});

document.addEventListener('focusin',e=>{if(e.target.id==='destination'&&state.entryMode==='direct'&&state.nativeField&&state.nativeField!=='where'){state.nativeField='where';render();$('#destination').focus()}});
